"""Client-ready markdown, in the same shape as CLIENT-SUMMARY.md."""

from __future__ import annotations

from datetime import date
from urllib.parse import urlparse

from audit import CATEGORY_ORDER, Assessment
from normalize import dedup_key

DISCLAIMER = (
    "Generated by a lightweight automated audit tool. This report is automated "
    "and needs a manual review before it is sent to a client or used in outreach. "
    "It does not confirm that an accreditation, an insurance policy, or a company number is valid."
)


def british_date(day: date) -> str:
    return f"{day.day} {day.strftime('%B %Y')}"


def render_markdown(assessment: Assessment, pagespeed: dict | None = None) -> str:
    pagespeed = pagespeed or {"skipped": True, "reason": "PSI_API_KEY is not set"}
    lines = ["# Quick Website Audit Summary", ""]
    firm = (assessment.firm_name or "").strip()
    if firm:
        lines.append(f"**Firm:** {firm}")
    lines.append(f"**Site:** {assessment.final_url}")
    lines.append(f"**Trade:** {assessment.trade_label}")
    lines.append(f"**Pages checked:** {assessment.pages_checked}")
    lines.append(f"**Date:** {british_date(assessment.audited_on)}")
    lines.append(f"**Score:** {assessment.score}/100")
    lines.append("")
    lines.append("## Overall")
    lines.append(_overall(assessment))
    lines.append("")
    lines.append("## Score")
    lines.append("")
    lines.append("| Area | Points |")
    lines.append("| --- | --- |")
    for category, awarded, maximum in _category_totals(assessment):
        lines.append(f"| {category} | {awarded}/{maximum} |")
    lines.append("")
    if assessment.penalties:
        bits = [f"{item['detail']} (−{item['points']})" for item in assessment.penalties]
        lines.append("Deductions: " + " ".join(bits))
        lines.append("")
    lines.append("## Key findings")
    lines.append("")
    findings = assessment.findings[:6]
    if not findings:
        lines.append("Nothing in this check produced a finding. A manual read is still worth doing before the summary is used.")
        lines.append("")
    else:
        for index, finding in enumerate(findings, start=1):
            lines.append(f"{index}. **{finding['title']}**  ")
            lines.append(finding["detail"])
            lines.append("")
    rest = assessment.findings[6:12]
    if rest:
        lines.append("## Also noted")
        lines.append("")
        for finding in rest:
            lines.append(f"- {finding['title']}")
        lines.append("")
    wins = _quick_wins(assessment)
    lines.append("## Quick wins")
    lines.append("")
    if not wins:
        lines.append("- No short edit stood out from this crawl.")
    else:
        for win in wins:
            lines.append(f"- {win}")
    lines.append("")
    notes = _page_notes(assessment)
    if notes:
        lines.append("## Other page notes")
        lines.append("")
        for note in notes:
            lines.append(f"- {note}")
        lines.append("")
    extra = _extra_notes(assessment, pagespeed)
    if extra:
        lines.append("## Notes")
        lines.append("")
        for note in extra:
            lines.append(f"- {note}")
        lines.append("")
    lines.append("---")
    lines.append(f"*{DISCLAIMER}*")
    lines.append("")
    return "\n".join(lines)


def _overall(assessment: Assessment) -> str:
    if assessment.pages_checked == 0:
        return (
            "The homepage could not be fetched, so this check has very little to go on. "
            "The score stays at 0 until the site can be opened."
        )
    score = assessment.score
    if score >= 95:
        lead = "The site covers the trust, contact, and technical points this check can see."
    elif score >= 85:
        lead = "The site covers most of the trust, contact, and technical points this check can see."
    elif score >= 70:
        lead = "The site is reasonably sound on the basics."
    elif score >= 50:
        lead = "The site has several gaps a commercial client would notice before getting in touch."
    else:
        lead = "The site is missing a number of the trust and contact signals this check looks for."
    positives = _positives(assessment)
    if positives:
        lead += " In its favour: " + "; ".join(positives) + "."
    if assessment.findings and score >= 85:
        lead += " One item still worth a look: " + _lower_first(assessment.findings[0]["title"]) + "."
    elif assessment.findings:
        titles = [_lower_first(finding["title"]) for finding in assessment.findings[:3]]
        lead += " The main items are: " + "; ".join(titles) + "."
    return lead


def _lower_first(title: str) -> str:
    title = title.rstrip(".")
    if not title:
        return title
    return title[0].lower() + title[1:]


def _positives(assessment: Assessment) -> list[str]:
    signals = assessment.signals
    items = []
    if signals.get("ukas_numbers"):
        items.append("UKAS is mentioned with an accreditation number")
    elif signals.get("ukas"):
        items.append("UKAS is mentioned")
    if signals.get("https"):
        items.append("the site uses HTTPS")
    if signals.get("phones") and signals.get("emails"):
        items.append("a phone number and an email address are present")
    if signals.get("current_terminology"):
        items.append("the pages use current survey terminology")
    return items[:3]


def _category_totals(assessment: Assessment) -> list[tuple[str, int, int]]:
    totals = []
    for category in CATEGORY_ORDER:
        rows = [item for item in assessment.items if item["category"] == category]
        totals.append(
            (
                category,
                sum(item["awarded"] for item in rows),
                sum(item["maximum"] for item in rows),
            )
        )
    return totals


def _quick_wins(assessment: Assessment) -> list[str]:
    wins = []
    for finding in assessment.findings:
        text = (finding.get("quick_win") or "").strip()
        if text and text not in wins:
            wins.append(text)
        if len(wins) >= 5:
            break
    return wins


def _page_notes(assessment: Assessment) -> list[str]:
    if not assessment.pages:
        return []
    home_key = dedup_key(assessment.final_url)
    lines = []
    for page in assessment.pages:
        if dedup_key(page.url) == home_key:
            continue
        path = urlparse(page.url).path or "/"
        for warning in page.warnings:
            lines.append(f"`{path}`: {warning}")
            if len(lines) >= 8:
                return lines
    return lines


def _extra_notes(assessment: Assessment, pagespeed: dict) -> list[str]:
    notes = []
    if pagespeed.get("skipped"):
        reason = pagespeed.get("reason") or "PSI_API_KEY is not set"
        notes.append(f"Google PageSpeed was not included ({reason}). It is not part of the score.")
    else:
        notes.append(
            f"Google PageSpeed mobile score: {pagespeed.get('mobile_score')}/100. This is separate from the audit score."
        )
    robots = [item for item in assessment.skipped if item.get("reason") == "robots.txt"]
    if robots:
        count = len(robots)
        notes.append(
            f"{count} URL{'s were' if count != 1 else ' was'} left unfetched because robots.txt disallows {'them' if count != 1 else 'it'}."
        )
    for note in assessment.notes:
        if note and note not in notes:
            notes.append(note)
    return notes
